(()=>{
  'use strict';
  const $=s=>document.querySelector(s),all=s=>Array.from(document.querySelectorAll(s));
  const root=document.documentElement,storageKey='gtstudy-v3-marks',colors=['gold','red','blue','green','purple'];
  const labels={forest:'林间纸页',ocean:'海盐晴蓝',violet:'葡萄暮紫',amber:'琥珀书灯'};
  const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}};
  const write=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));return true}catch{return false}};
  function say(text){const el=$('#study-toast');el.textContent=text;el.hidden=false;clearTimeout(say.timer);say.timer=setTimeout(()=>el.hidden=true,3300)}
  function paletteUI(){all('[data-palette-choice]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.paletteChoice===root.dataset.palette));all('[data-study-night]').forEach(b=>b.setAttribute('aria-pressed',root.dataset.scheme==='dark'))}
  all('[data-palette-choice]').forEach(b=>b.onclick=()=>{root.dataset.palette=b.dataset.paletteChoice;try{localStorage.setItem('gtstudy-v3-palette',b.dataset.paletteChoice)}catch{}paletteUI();all('.theme-live').forEach(el=>el.textContent='已切换：'+labels[b.dataset.paletteChoice]);if(!matchMedia('(prefers-reduced-motion:reduce)').matches&&!document.body.classList.contains('motion-off'))b.animate([{scale:'.97'},{scale:'1'}],{duration:220})});
  if(root.dataset.scheme==='dark')document.body.classList.add('night');
  function nightState(){root.dataset.scheme=document.body.classList.contains('night')?'dark':'light';paletteUI()}
  all('[data-study-night]').forEach(b=>b.onclick=()=>{document.body.classList.toggle('night');write('creeds-v1-night',document.body.classList.contains('night'));nightState()});
  new MutationObserver(nightState).observe(document.body,{attributes:true,attributeFilter:['class']});paletteUI();
  let essentialIndex=-1;
  $('#essential-step')?.addEventListener('click',()=>{const cards=all('[data-essential]');essentialIndex=(essentialIndex+1)%cards.length;cards.forEach((el,i)=>el.classList.toggle('is-active',i===essentialIndex));const active=cards[essentialIndex];if(active&&!matchMedia('(prefers-reduced-motion:reduce)').matches&&!document.body.classList.contains('motion-off'))active.animate([{transform:'translateY(8px)',opacity:.6},{transform:'translateY(0)',opacity:1}],{duration:420,easing:'ease-out'});$('#essential-step').textContent=['① 先认清救主','② 再看救恩成就','③ 领受并结出果子'][essentialIndex]+' →'});

  const pages=new Set(['index.html','library.html','background.html','reader-apostles.html','reader-nicene.html','reader-athanasian.html']);
  const scopes=new Map();
  function register(el,key,label){if(!el||scopes.has(key))return;el.dataset.noteScope=key;el.dataset.noteLabel=label;scopes.set(key,el)}
  all('[data-note-scope]').forEach(el=>register(el,el.dataset.noteScope,el.closest('.clause')?.querySelector('h3')?.textContent||'核心笔记'));
  all('.clause[id]').forEach(clause=>{const label=clause.querySelector('h3')?.textContent||clause.id;all('#'+clause.id+' .clause-body>p').forEach((el,i)=>register(el,'explanation:'+clause.id+':'+i,label));clause.querySelectorAll('.clause-bottom>div').forEach((el,i)=>register(el,'application:'+clause.id+':'+i,label))});
  all('.original-body').forEach((body,i)=>{let key=body.closest('[id]')?.id||'';if(key.startsWith('original-'))key=key.slice(9);else if(/^(apostles|nicene|athanasian)-1$/.test(key))key=key.slice(0,-2);else if(document.body.classList.contains('clean-page'))key=(location.pathname.match(/reader-(apostles|nicene|athanasian)/)||[])[1]||'reader';if(!key)key='source-'+i;const blocks=Array.from(body.querySelectorAll('p,h2,h3,h4,h5,li')).filter(el=>!el.querySelector('p,li,h2,h3,h4,h5'));blocks.forEach((el,j)=>register(el,'original:'+key+':'+j,body.closest('article,section,main,.original-panel')?.querySelector('h1,h2,h3')?.textContent||'信经原文'))});
  const guideCounters={};all('.reading-context p,.central-question p,.covenant-link>p,.bible-steps p,.stakes-banner p,.essential-card>p').forEach(el=>{const section=el.closest('section[id]')?.id||'overview';const i=guideCounters[section]||0;guideCounters[section]=i+1;register(el,'guide:'+section+':'+i,el.closest('article,.central-question,.covenant-link')?.querySelector('h3,h4')?.textContent||'核心导读')});

  function valid(n){return n&&typeof n==='object'&&typeof n.id==='string'&&/^[a-zA-Z0-9_-]{1,100}$/.test(n.id)&&typeof n.scope==='string'&&n.scope.length<200&&Number.isInteger(n.start)&&Number.isInteger(n.end)&&n.start>=0&&n.end>n.start&&n.end-n.start<=5000&&typeof n.quote==='string'&&n.quote.length===n.end-n.start&&typeof n.note==='string'&&n.note.length<=5000&&n.styles&&colors.includes(n.styles.color)&&['none','solid','dashed'].includes(n.styles.underline)&&pages.has(n.page)&&typeof n.anchor==='string'&&/^[\w:-]{0,150}$/.test(n.anchor)}
  let notes=read(storageKey,[]);notes=Array.isArray(notes)?notes.filter(valid).slice(0,1000):[];
  let visible=document.body.classList.contains('clean-page')?false:read('gtstudy-v3-marks-visible',true),pending=null,editingId=null;
  document.body.classList.toggle('notes-hidden',!visible);
  function persist(){if(!write(storageKey,notes))say('浏览器暂不能保存，请先导出笔记备份');updateCounts()}
  function updateCounts(){all('.note-count').forEach(el=>el.textContent=notes.length);all('[data-notes-visible]').forEach(b=>{b.setAttribute('aria-pressed',visible);b.textContent=visible?'隐藏我的标记':'显示我的标记'})}
  function unwrap(el){Array.from(el.querySelectorAll('[data-personal-mark]')).reverse().forEach(span=>span.replaceWith(...span.childNodes));el.normalize()}
  function renderBlock(key){const el=scopes.get(key);if(!el)return;unwrap(el);if(!visible)return;const text=el.textContent;const active=notes.filter(n=>n.scope===key&&text.slice(n.start,n.end)===n.quote);if(!active.length)return;const walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);const nodes=[];let offset=0,node;while(node=walker.nextNode()){nodes.push({node,start:offset,end:offset+node.data.length});offset+=node.data.length}
    for(const item of nodes){const relevant=active.filter(n=>n.start<item.end&&n.end>item.start);if(!relevant.length)continue;const boundaries=new Set([0,item.node.data.length]);relevant.forEach(n=>{boundaries.add(Math.max(0,n.start-item.start));boundaries.add(Math.min(item.node.data.length,n.end-item.start))});const cuts=[...boundaries].sort((a,b)=>a-b),frag=document.createDocumentFragment();for(let i=0;i<cuts.length-1;i++){const start=cuts[i],end=cuts[i+1];if(start===end)continue;const covers=relevant.filter(n=>n.start<item.start+end&&n.end>item.start+start);const value=item.node.data.slice(start,end);if(!covers.length){frag.append(document.createTextNode(value));continue}const span=document.createElement('span');span.dataset.personalMark='true';span.dataset.markIds=covers.map(n=>n.id).join(',');span.className='personal-mark';if(covers.some(n=>n.styles.bold))span.classList.add('note-bold');const ink=covers.filter(n=>n.styles.ink).at(-1),fill=covers.filter(n=>n.styles.fill).at(-1),line=covers.filter(n=>n.styles.underline!=='none').at(-1);if(ink){span.classList.add('note-ink');span.style.setProperty('--mark-ink','var(--note-ink-'+ink.styles.color+')')}if(fill){span.classList.add('note-fill');span.style.setProperty('--mark-fill','var(--note-fill-'+fill.styles.color+')')}if(line){span.classList.add('note-'+line.styles.underline);span.style.setProperty('--mark-line','var(--note-line-'+line.styles.color+')')}span.textContent=value;span.title=covers.map(n=>n.note).filter(Boolean).join('\n')||'点击查看此处标记';frag.append(span)}item.node.replaceWith(frag)}
  }
  function renderAll(){for(const [key,el]of scopes)if(notes.some(n=>n.scope===key)||el.querySelector('[data-personal-mark]'))renderBlock(key);updateCounts()}
  renderAll();
  all('[data-notes-visible]').forEach(b=>b.onclick=()=>{visible=!visible;write('gtstudy-v3-marks-visible',visible);document.body.classList.toggle('notes-hidden',!visible);renderAll();say(visible?'已显示本机标记':'已切换清爽阅读，标记仍保存在本机')});
  function capture(){if(document.querySelector('dialog[open]'))return;const selection=window.getSelection();if(!selection||selection.isCollapsed||!selection.rangeCount){$('#selection-tools').hidden=true;return}const range=selection.getRangeAt(0);const startEl=range.startContainer.nodeType===Node.ELEMENT_NODE?range.startContainer:range.startContainer.parentElement;const endEl=range.endContainer.nodeType===Node.ELEMENT_NODE?range.endContainer:range.endContainer.parentElement;const block=startEl.closest('[data-note-scope]');if(!block||endEl.closest('[data-note-scope]')!==block){$('#selection-tools').hidden=true;return}const prefix=range.cloneRange();prefix.selectNodeContents(block);try{prefix.setEnd(range.startContainer,range.startOffset)}catch{return}const start=prefix.toString().length,end=start+range.toString().length,quote=block.textContent.slice(start,end);if(!quote.trim()||quote.length>5000){$('#selection-tools').hidden=true;return}pending={scope:block.dataset.noteScope,start,end,quote,label:block.dataset.noteLabel||'学习笔记',anchor:block.closest('[id]')?.id||'top',page:location.pathname.split('/').filter(Boolean).at(-1)||'index.html'};if(!pages.has(pending.page)){if(pages.has(pending.page+'.html'))pending.page+='.html';else pending.page='index.html'};$('#selection-preview').textContent='已选：'+quote.slice(0,22)+(quote.length>22?'…':'');$('#selection-tools').hidden=false}
  let selectionTimer;document.addEventListener('selectionchange',()=>{clearTimeout(selectionTimer);selectionTimer=setTimeout(capture,130)});document.addEventListener('pointerup',()=>{clearTimeout(selectionTimer);selectionTimer=setTimeout(capture,60)});
  $('#selection-tools').addEventListener('pointerdown',e=>e.preventDefault());$('#selection-dismiss').onclick=()=>{$('#selection-tools').hidden=true;window.getSelection()?.removeAllRanges()};
  function addMark(styles,note=''){if(!pending)return say('请先在同一段中选择要标记的文字');if(notes.length>=1000&&!editingId)return say('标记数量较多，请先导出备份并整理');const id=crypto.randomUUID?.()||('n'+Date.now()+'-'+Math.random().toString(36).slice(2));if(editingId){notes=notes.map(n=>n.id===editingId?{...n,styles,note,updated:new Date().toISOString()}:n);editingId=null}else notes.push({...pending,id,styles,note,created:new Date().toISOString()});visible=true;write('gtstudy-v3-marks-visible',true);document.body.classList.remove('notes-hidden');persist();renderBlock(pending.scope);$('#selection-tools').hidden=true;window.getSelection()?.removeAllRanges();say('已保存到本机 · '+(note?'含个人笔记':'原文文字未改动'))}
  all('[data-quick-mark]').forEach(b=>b.onclick=()=>{const mode=b.dataset.quickMark;addMark({bold:mode==='bold',ink:false,fill:mode==='fill',underline:mode==='solid'?'solid':mode==='dashed'?'dashed':'none',color:mode==='solid'?'blue':mode==='dashed'?'red':'gold'})});
  $('#mark-custom').onclick=()=>{if(!pending)return;editingId=null;$('#mark-form').reset();$('#mark-quote').textContent=pending.quote;$('#mark-note').value='';$('#selection-tools').hidden=true;$('#mark-editor').showModal()};
  all('[data-close-dialog]').forEach(b=>b.onclick=()=>b.closest('dialog').close());
  $('#mark-form').onsubmit=e=>{e.preventDefault();const form=e.currentTarget;const styles={bold:form.elements.bold.checked,ink:form.elements.ink.checked,fill:form.elements.fill.checked,underline:form.elements.underline.value,color:form.elements.color.value};if(!styles.bold&&!styles.ink&&!styles.fill&&styles.underline==='none')styles.fill=true;addMark(styles,$('#mark-note').value);$('#mark-editor').close()};
  function openNotes(focusId){$('#selection-tools').hidden=true;const list=$('#notes-list');list.replaceChildren();if(!notes.length){const empty=document.createElement('p');empty.className='empty-notes';empty.textContent='还没有个人标记。先选中原文或解读中的一句话，再选择一种标记方式。';list.append(empty)}for(const n of [...notes].reverse()){const card=document.createElement('article');card.className='personal-note-card';card.dataset.noteId=n.id;const h=document.createElement('h3');h.textContent=n.label||'学习笔记';const quote=document.createElement('blockquote');quote.textContent=n.quote;const tag=document.createElement('div');tag.className='note-style-tags';tag.textContent=[n.styles.bold?'加粗':'',n.styles.ink?'字体色':'',n.styles.fill?'底纹':'',n.styles.underline==='solid'?'实线':n.styles.underline==='dashed'?'虚线':''].filter(Boolean).join(' · ');const p=document.createElement('p');p.className='user-note';p.textContent=n.note;const actions=document.createElement('div');actions.className='personal-note-actions';const locate=document.createElement('button');locate.type='button';locate.textContent='定位原文';locate.onclick=()=>{$('#notes-library').close();const target=scopes.get(n.scope);if(target){target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'center'});if(typeof target.animate==='function'&&!matchMedia('(prefers-reduced-motion:reduce)').matches)target.animate([{outline:'2px solid var(--gold)'},{outline:'2px solid transparent'}],{duration:1800})}else location.href=n.page+'#'+encodeURIComponent(n.anchor)};const edit=document.createElement('button');edit.type='button';edit.textContent='编辑标记';edit.onclick=()=>{editingId=n.id;pending={...n};$('#notes-library').close();$('#mark-quote').textContent=n.quote;$('#mark-note').value=n.note;const f=$('#mark-form');for(const k of ['bold','ink','fill'])f.elements[k].checked=Boolean(n.styles[k]);f.elements.underline.value=n.styles.underline;f.elements.color.value=n.styles.color;$('#mark-editor').showModal()};const del=document.createElement('button');del.type='button';del.textContent='删除此标记';del.onclick=()=>{notes=notes.filter(x=>x.id!==n.id);persist();renderBlock(n.scope);openNotes()};actions.append(locate,edit,del);card.append(h,quote,tag);if(n.note)card.append(p);card.append(actions);list.append(card)}$('#notes-status').textContent=`${notes.length} 个标记 · 本机保存，可导出备份`;if(!$('#notes-library').open)$('#notes-library').showModal();if(focusId)list.querySelectorAll('[data-note-id]').forEach(card=>{if(card.dataset.noteId===focusId)card.scrollIntoView({block:'nearest'})})}
  all('[data-notes-open]').forEach(b=>b.onclick=()=>openNotes());document.addEventListener('click',e=>{const mark=e.target.closest('[data-mark-ids]');if(mark&&!document.body.classList.contains('notes-hidden')&&window.getSelection()?.isCollapsed)openNotes(mark.dataset.markIds.split(',')[0])});
  $('#notes-export').onclick=()=>{const payload={format:'GTstudy notes',version:1,exported:new Date().toISOString(),notes};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='GTstudy-notes-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);$('#notes-status').textContent='已导出笔记文件。可在其他站点导入。'};
  $('#notes-import').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>3_000_000)return say('请导入小于3MB的笔记文件');try{const imported=JSON.parse(await file.text());if(imported.format!=='GTstudy notes'||imported.version!==1||!Array.isArray(imported.notes))throw Error();const incoming=imported.notes.filter(valid),existing=new Set(notes.map(n=>n.id));notes.push(...incoming.filter(n=>!existing.has(n.id)).slice(0,1000-notes.length));persist();renderAll();openNotes();$('#notes-status').textContent='已导入有效笔记，重复记录自动略过。'}catch{say('文件格式不符合GTstudy笔记格式，未导入')}e.target.value=''};
  $('#notes-clear').onclick=()=>{if(!notes.length)return;if(!window.confirm('清空此浏览器中的所有GTstudy个人标记？建议先导出备份。'))return;notes=[];persist();renderAll();openNotes()};
  window.addEventListener('storage',e=>{if(e.key===storageKey){const incoming=read(storageKey,[]);notes=Array.isArray(incoming)?incoming.filter(valid).slice(0,1000):[];renderAll()}});
  document.addEventListener('keydown',e=>{if(e.altKey&&e.key.toLowerCase()==='m'){capture();if(pending){e.preventDefault();$('#mark-custom').click()}}if(e.key==='Escape')$('#selection-tools').hidden=true});
})();
